def average(values, *, digits=1):
    """Average of the values, rounded."""
    values = list(values)
    return round(sum(values) / len(values), digits) if values else 0

def min_max(values):
    return min(values), max(values)

scores = [72, 95, 88, 64]
low, high = min_max(scores)
print(average(scores), average(scores, digits=0), low, high)

import os
import requests

def ask(question: str) -> str:
    try:
        response = requests.post(
            "https://api.example.com/v1/answers",
            json={"question": question},
            headers={"Authorization": f"Bearer {os.environ['API_KEY']}"},
            timeout=30,
        )
        response.raise_for_status()
        return response.json().get("answer", "(no answer)")
    except requests.exceptions.Timeout:
        return "The service took too long. Try again."
    except requests.exceptions.RequestException as error:
        return f"Request failed: {error}"
